export const brands = Array.from(new Set(products.map((product) => product.brand)));

export const topNavigation = categories;

/** تنسيق السعر بالريال السعودي مع رقمين عشريين */
export function formatPrice(price: number): string {
  return `${price.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ر.س`;
}

export function getCategory(slug?: string) {
  return categories.find((category) => category.slug === slug) ?? categories[0];
}

export function getProduct(slug?: string) {
  return products.find((product) => product.slug === slug) ?? products[0];
}

export function getProductsForCategory(slug?: string) {
  if (!slug) return products;
  return products.filter((product) => product.category === slug);
}
